{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C13", "C19", "C22", "C04", "C24", "C31", "C34", "C35"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C13", "C19", "C22", "C04", "C24", "C31", "C34", "C35"],
  "claims": [
    {
      "claim": "The query is moclobemide (4-chloro-N-(2-morpholinoethyl)benzamide); L3 records C34/C35 report oral moclobemide Tmax values of about 1.44–1.46 h in humans, demonstrating rapid oral absorption after single oral dosing.",
      "card_ids": ["C34", "C35"]
    },
    {
      "claim": "The close structural analog procainamide has measured absolute oral bioavailability values of 75% by AUC ratio (C13), 71 ± 18% by urinary excretion (C19), 92% in one patient (C22), and 0.68 for a sustained-release formulation (C04), all well above the 20% threshold; L2 context adds procainamide 75–85% (C24) and acecainide 85% (C31).",
      "card_ids": ["C13", "C19", "C22", "C04", "C24", "C31"]
    },
    {
      "claim": "The physicochemical prior is favorable (MW 268 Da, logD 1.34, TPSA 41.6 Å², neutral fraction 0.88), and no supplied record affirmatively shows F < 20% for the query or its close analog under fed conditions.",
      "card_ids": ["C13", "C19", "C22", "C04", "C34", "C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C34", "C35"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for moclobemide itself was supplied; the decision relies on structural analogy to procainamide, the physicochemical prior, and indirect oral-exposure records.",
    "C34/C35 provide Tmax but not AUC or Cmax magnitude, so they confirm absorption but do not directly quantify F.",
    "No fed-state-specific bioavailability or exposure record is available; the fed condition is not shown to reduce F below 20%.",
    "No direct first-pass metabolism, transporter, or formulation data for the query were supplied."
  ],
  "decision_summary": "The query is moclobemide, a low-MW, moderately lipophilic, mostly neutral para-chlorobenzamide with a morpholinoethyl amide side chain. L3 adds direct human oral-exposure records for moclobemide showing rapid absorption (Tmax ~1.4 h), while the close analog procainamide has measured absolute oral bioavailability values of 68–92%, all well above 20%. The favorable physicochemical prior and absence of affirmative low-F evidence support a high prediction; confidence remains moderate because no direct F value for moclobemide was supplied."
}

